#include <vector>

class Solution {
public:
    int findTreeRoot(int n, std::vector<std::vector<int>>& edges, std::vector<int>& colors) {
        std::vector<int> indegree(n, 0);
        for (auto const& e : edges) {
            indegree[e[1]]++;
        }
        for (int i = 0; i < n; ++i) {
            if (indegree[i] == 0) return i;
        }
        return -1;
    }
};

class Solution {
    public int findTreeRoot(int n, int[][] edges, int[] colors) {
        int[] indegree = new int[n];
        for (int[] e : edges) {
            indegree[e[1]]++;
        }
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) return i;
        }
        return -1;
    }
}

